def agent_loop(call, tools, user_message, run_tool, max_turns=10):
    messages = [{"role": "user", "content": user_message}]
    for turn in range(1, max_turns + 1):
        resp = call(messages)
        stop = resp.get("stop_reason")
        if stop == "refusal":
            raise RuntimeError("the model declined this request")
        if stop == "max_tokens":
            raise RuntimeError("the reply hit the output cap and was truncated")
        if stop == "end_turn":
            text = "".join(b.get("text", "") for b in resp["content"]
                           if b.get("type") == "text")
            return {"text": text, "turns": turn, "messages": messages}
        if stop != "tool_use":
            raise RuntimeError(f"unexpected stop reason {stop!r}")
        messages.append({"role": "assistant", "content": resp["content"]})
        results = []
        for block in resp["content"]:
            if block.get("type") != "tool_use":
                continue
            results.append({
                "type": "tool_result",
                "tool_use_id": block["id"],
                "content": run_tool(block["name"], block["input"]),
            })
        messages.append({"role": "user", "content": results})
    raise RuntimeError("the loop did not finish within max_turns")
